from pathlib import Path
OUT = Path(__file__).resolve().parent / "notebooks" / 'U5-L4_语音问答闭环.ipynb'
def md(s):
    return {"cell_type": "markdown", "metadata": {}, "source": s.splitlines(keepends=True)}
def code(s):
    return {"cell_type": "code", "metadata": {}, "execution_count": None, "outputs": [], "source": s.splitlines(keepends=True)}
cells = []
cells.append(md('# U5-L4：语音问答闭环\n\n**课程目标**\n\n1. 能说明采音、语音转写、回复生成、语音合成与播放各自处理什么，区分一轮问答与持续会话。\n2. 能画出会话管理的状态与转换条件，区分程序记录的使用状态和 SDK 任务状态。\n3. 能运行并调整会话管理程序，完成启动、阻止重复启动、停止和再次启动，依据实际输出填写记录。\n'))
cells.append(md('## 一、本课要解决的问题\n\n前三课分别接触了语音识别、语音合成和 LLM 对话。在 L3 中，机器人回答完一个问题后，还可以接着回答下一个问题。我们用 `wait()` 保持程序等待，结束练习时再中断运行、取消任务。\n\n一次回答结束，会话通常还在继续。如果应用已经启动了一个会话，用户又按了一次“开始”，程序该怎样处理？用户按下“停止”后，又要根据什么判断可以重新开始？\n\n> **怎样让一个会话按要求开始、持续使用，并在确认停止后允许再次启动？**\n'))
cells.append(md('## 二、一轮问答与持续会话\n\n### 2.1 语音问答的功能过程\n\n| 功能 | 输入 | 输出 | 前三课的对应内容 |\n|---|---|---|---|\n| 采音 | 空气中的声音 | 音频采样数据 | L1 录音与声音块 |\n| 语音转写（ASR） | 音频 | 识别出的文字 | L1 `recognize_stream()` |\n| 回复生成（LLM） | 问题、设定和已有对话内容 | 回复内容 | L3 人设与对话 |\n| 语音合成（TTS） | 待说的文字 | 音频数据 | L2 `synthesize()` |\n| 播放 | 音频数据 | 扬声器发出的声音 | L1、L2 播放声音 |\n\nASR 输出文字，并不保证已经正确理解了提问。LLM 生成的回复也需要核查事实。各项功能的部署位置和网络依赖，要以实际使用的服务配置为准。\n\n`chat()` 将持续语音对话封装为一个任务。上表用于理解功能之间的关系；不能据此断定 SDK 内部每一步都要完整结束后才开始下一步。\n'))
cells.append(md('### 2.2 任务句柄能告诉我们什么\n\n`chat()` 返回 `TaskHandle[None]`。句柄可以查询整个任务的状态，却没有公开“一轮回答已经说完”的事件，也没有分别表示正在转写、生成回复或播放的状态。\n\n| 接口或字段 | 能得到的信息 | 使用时要分清的边界 |\n|---|---|---|\n| `task.status` | 整个任务的 SDK 状态 | `RUNNING` 不能说明此刻在听还是在说 |\n| `task.done()` | 是否已经进入终态 | 回答完一句话，不等于整个会话进入终态 |\n| `task.error` | 任务错误信息 | 本课在 `FAILED` 时查看，正常取消不按故障处理 |\n| `task.cancel()` | 是否成功提交取消请求 | 返回 `True` 后仍需确认任务是否结束 |\n| `task.wait(timeout=5.0)` | 等待结束或超时后的任务状态 | 超时不会自动取消任务，也不表示一轮回答结束 |\n\n`PENDING`（等待执行）、`RUNNING`（执行中）、`CANCELLING`（取消中）都属于非终态。`SUCCEEDED`、`FAILED`、`CANCELLED` 是终态，`done()` 在这三种情况下返回 `True`。`running()` 只判断是否为 `RUNNING`，所以 `running()` 为 `False` 时，任务仍可能处于等待或取消过程中。\n\nL2 的 `synthesize()` 是处理一段有限文本的任务，成功后可用 `result()` 取得音频。官方还提供对一段有限音频转写的 `recognize()`，成功后可取得文字；它有单声道等输入要求，不能直接套用 L1 的三声道录音。两者都不能提供 `chat()` 内部某一轮问答的完成信号。\n'))
cells.append(md('### 2.3 从等待会话到管理会话\n\nL3 用不带超时的 `wait()` 等待整个会话结束，适合连续进行人设问答。等待期间，当前代码格不会执行后面的语句。用固定的 `sleep(10)` 替代，也只能让程序等待十秒，不能判断机器人是否说完。\n\n本课在 `chat()` 返回后保存句柄，让当前代码格执行完。机器人仍可继续对话，我们则可以运行下一格，查看或停止同一个任务。SDK 的异步调用使这种操作成为可能，本课不需要创建线程。\n'))
cells.append(md('## 三、观察一个持续会话\n\n⚠️ **注意**：本课只使用麦克风和扬声器，不发送运动指令。音量保持适中，各组错开说话。开始前先结束 L1～L3 留下的录音、识别和聊天任务；不要同时运行多个语音 Notebook。\n\n📌 **前置准备**：完成机器人开机、配网和 IP 确认，电脑与机器人连接同一 WiFi，并已能用 BoosterStudio 连接。机器人保持教师确认的稳定姿态，本课不切换运动模式。如果从前一课的行走实验接续，先按该课流程停止运动、回到 `prepare` 并确认站稳；需要坐下收起时，先在 `prepare` 模式站稳，由人工支撑，再进入 `damping` 并扶坐，严禁从 `walk` 直接切到 `damping`。\n\n### 3.1 连接与初始化\n\n**STEP 01：** 连接机器人，建立保存会话的变量。\n\n<font color="red">提示：</font>下面的初始化格只在本课开始、确认没有遗留任务时运行一次。会话启动后不要重跑它：把变量重新赋为 `None`，不会停止后台任务，却会丢失用于管理它的句柄。如果已丢失句柄，先请教师协助结束旧任务，不要继续新建会话。\n'))
cells.append(code('from boosteros.robots.booster import BoosterRobot\nfrom boosteros.brain import Speech\nfrom boosteros.brain.speech import ChatConfig\n\nrobot = BoosterRobot()\nspeech = Speech(robot)\nrobot.audio_manager.set_system_volume(0.5)\n\nPROMPT = "你是机器人实训室的讲解员。用简短、清楚的中文回答；没有提供的场地信息，请说明需要向教师确认。"\nchat_task = None\napp_state = "待机"\n\nprint("已连接：", robot.robot_info.model, robot.robot_info.serial_number)\nprint("应用状态：", app_state)\n'))
cells.append(md('### 3.2 启动并连续问答\n\n**STEP 02：** 发起一个会话，连续问两个问题，例如“这门课练习什么？”和“什么是语音识别？”。再问一次“你刚才解释了什么？”，观察同一个会话能否结合前文回答。\n\n下一格会先检查是否已有未结束的任务。句柄返回后显示“会话已发起”，只说明调用已经返回；是否能正常交互，还要通过实际问答观察。没有回答时不要反复启动，先查看状态和设备连接。\n'))
cells.append(code('if chat_task is None or chat_task.done():\n    chat_task = speech.chat(\n        config=ChatConfig(system_prompt=PROMPT, volume=0.5),\n        enable_subtitle_log=True,\n    )\n    app_state = "会话已发起"\n    print("应用状态：", app_state, "；SDK 状态：", chat_task.status)\nelse:\n    print("已有未结束的会话，保留原句柄。SDK 状态：", chat_task.status)\n'))
cells.append(md('**STEP 03：** 回答结束后查看任务。\n\n先听机器人把回答说完，再运行下一格。记录 `status` 和 `done()`。这个检查发生在你选择运行的时刻，不能用它测量回答完成的准确时刻。\n\n随后重跑 STEP 02，观察程序是否拦住重复启动。再问一个问题，检查原会话是否仍可使用。\n'))
cells.append(code('print("应用状态：", app_state)\nprint("SDK 状态：", chat_task.status)\nprint("任务是否进入终态：", chat_task.done())\nif chat_task.status == "FAILED":\n    print("错误信息：", chat_task.error)\n'))
cells.append(md('### 3.3 打断说话与结束会话\n\nL3 已用过 `chat()` 的打断功能。机器人说话时，可以尝试说“停一下”；是否打断成功，以现场现象为准。随后再问一个问题，并运行 STEP 03。\n\n“停一下”是会话中的语音打断词。它与程序调用 `cancel()` 的用途不同：打断当前说话后，会话仍可能继续接收新问题；取消请求用于结束整个任务。\n\n**STEP 04：** 停止当前会话，检查请求和最终状态。\n\n下面的五秒是本次停止操作愿意等待的时间。若等待后仍未进入终态，保留原句柄，稍后重新查看；不要另开会话。\n'))
cells.append(code('if chat_task is None:\n    print("还没有创建会话。")\nelif chat_task.done():\n    app_state = "待机"\n    print("任务已经结束：", chat_task.status)\nelse:\n    accepted = chat_task.cancel()\n    print("取消请求是否成功提交：", accepted)\n    if accepted:\n        app_state = "停止请求已发出"\n        chat_task.wait(timeout=5.0)\n    if chat_task.done():\n        app_state = "待机"\n    print("应用状态：", app_state, "；SDK 状态：", chat_task.status)\n    if not chat_task.done():\n        print("尚未确认结束，请保留句柄，稍后查看。")\n\nif chat_task is not None and chat_task.status == "FAILED":\n    print("错误信息：", chat_task.error)\n'))
cells.append(md('## 四、用状态机管理操作\n\n### 4.1 状态与转换条件\n\n程序用 `app_state` 记录自己的管理状态。**状态机**由有限的状态和明确的转换条件组成。本课的状态描述应用已经做了什么；SDK 状态描述任务处于什么生命周期阶段。\n\n| 应用状态 | 含义 | 允许的操作与转换 |\n|---|---|---|\n| 待机 | 没有任务，或旧任务已确认进入终态 | “开始”创建新会话，转为“会话已发起” |\n| 会话已发起 | 已保存会话句柄，尚未确认任务结束 | 可查看；重复开始时保留旧任务；取消请求提交成功后转为“停止请求已发出” |\n| 停止请求已发出 | 已成功提交取消请求，仍需核查结果 | 可查看，暂不允许重开；确认 `done()` 为真后回到“待机” |\n\n任务也可能因失败而结束。查看时发现 `done()` 为真，应用可以回到待机；若是 `FAILED`，先记录 `error`、请教师核查原因，再决定是否重试。\n\n请画出这三个状态之间的箭头，在箭头上写出条件。补上“重复开始”和“取消请求未成功提交”时应保留在哪个状态。\n'))
cells.append(md('### 4.2 三种操作共用一个管理函数\n\n**STEP 05：** 定义会话管理函数。\n\n`manage_chat()` 接收操作文字、旧句柄和应用状态，返回更新后的句柄与状态。函数开头先检查旧任务是否结束；后面的分支处理“开始”“查看”“停止”。\n\n对照 STEP 02～04 阅读下面的代码，找出拦住重复启动的条件。这里使用 `done()`，以便把等待执行、执行中、取消中都视为尚未结束。\n'))
cells.append(code('def manage_chat(command, task, state):\n    if task is not None and task.done():\n        print("旧任务终态：", task.status)\n        if task.status == "FAILED":\n            print("错误信息：", task.error)\n        state = "待机"\n\n    if command == "开始":\n        if task is None or task.done():\n            task = speech.chat(\n                config=ChatConfig(system_prompt=PROMPT, volume=0.5),\n                enable_subtitle_log=True,\n            )\n            state = "会话已发起"\n        else:\n            print("已有未结束的会话，本次不重复创建。")\n\n    elif command == "查看":\n        if task is None:\n            print("还没有创建会话。")\n\n    elif command == "停止":\n        if task is None or task.done():\n            print("当前没有需要停止的任务。")\n        else:\n            accepted = task.cancel()\n            print("取消请求是否成功提交：", accepted)\n            if accepted:\n                state = "停止请求已发出"\n                task.wait(timeout=5.0)\n            if task.done():\n                state = "待机"\n            else:\n                print("尚未确认结束，请保留句柄，稍后查看。")\n    else:\n        print("操作文字应为：开始、查看、停止。")\n\n    # 任务也可能在上面的操作过程中结束，再核查一次。\n    if task is not None and task.done():\n        state = "待机"\n    print("应用状态：", state)\n    if task is not None:\n        print("SDK 状态：", task.status, "；是否终态：", task.done())\n        if task.status == "FAILED":\n            print("错误信息：", task.error)\n    return task, state\n'))
cells.append(md('**STEP 06：** 操作同一个会话。\n\n每次修改下一格的 `command`，运行一次，并记录结果。按以下顺序操作：\n\n1. “查看”：确认 STEP 04 的旧任务是否已结束。\n2. “开始”：确认旧任务已结束后，发起新会话并完成问答。\n3. 再次“开始”：观察重复启动是否被拦住；继续使用原会话。\n4. “停止”，再“查看”：记录取消请求和最终状态。如果仍是非终态，继续查看、暂不重开。\n5. 确认终态后再次“开始”，完成问答；最后“停止”并核查终态。\n\n<font color="red">提示：</font>两个函数返回值要同时保存，`chat_task, app_state = ...` 分别接收更新后的句柄与状态。不要只调用函数而丢弃返回的句柄。\n'))
cells.append(code('command = "查看"  # 每次改成“开始”“查看”或“停止”，再运行这一格\nchat_task, app_state = manage_chat(command, chat_task, app_state)\n'))
cells.append(md('### 4.3 根据条件补写判断\n\n**STEP 07：** 在旧任务仍未结束时，试着解释为什么不允许重新开始。\n\n下一格的 `can_start` 暂时设为 `False`。请把它改为一个条件表达式：没有旧任务，或者旧任务已进入终态时，结果为 `True`。分别在会话使用中、停止请求发出后、确认终态后三种情况下检查结果。若取消很快完成，记录实际终态即可，不必人为制造取消卡住的情况。\n'))
cells.append(code('can_start = False  # 请替换为允许启动的条件；本格只判断，不创建任务\nprint("当前是否允许启动：", can_start)\n'))
cells.append(md('### 4.4 结束练习\n\n**STEP 08：** 发送停止操作，再次查看结果。\n\n练习结束前，应确认旧任务已经进入终态。若五秒后仍未结束，请保留变量、停止重复启动，并请教师检查。Notebook 代码格运行结束或被中断，都不能单独证明后台会话已经退出。\n'))
cells.append(code('chat_task, app_state = manage_chat("停止", chat_task, app_state)\nchat_task, app_state = manage_chat("查看", chat_task, app_state)\n'))
cells.append(md('## 五、观察与记录\n\n### 5.1 会话操作记录\n\n| 操作或观察时机 | 应用状态 | SDK 状态 / `done()` | 实际问答或程序提示 |\n|---|---|---|---|\n| 首次开始后 | | | |\n| 回答完一个问题后查看 | | | |\n| 同一会话继续提问 | | | |\n| 未结束时重复开始 | | | |\n| 说“停一下”后继续提问 | | | |\n| 停止请求提交后 | | | |\n| 再次查看，确认终态 | | | |\n| 再次开始并问答 | | | |\n| 最后停止并确认终态 | | | |\n\n本次 `cancel()` 返回值：______；最终状态：______。如果没有观察到短暂的 `PENDING` 或 `CANCELLING`，按实际结果填写。\n\n### 5.2 检查点\n\n- 能否按输入输出解释采音、ASR、LLM、TTS 和播放，并说明一轮回答结束后会话为何仍可继续。\n- 能否区分 `app_state` 与 `task.status`，为状态图的每条转换写出可判断的条件。\n- 能否保留旧句柄，拦住重复开始，并在确认终态后重新启动。\n\n### 5.3 学习评价\n\n1. 判断：`chat_task.status == "RUNNING"` 表示机器人此刻正在生成回答。（\u3000）\n2. 判断：`cancel()` 返回 `True`，或者 `wait(timeout=5.0)` 返回，都足以证明任务已经结束。（\u3000）\n3. 填空：没有旧任务，或旧任务的 ______ 返回 `True` 时，本课管理程序才允许开始新会话。\n\n> 参考答案（教师留存，勿印发给学生）\n>\n> 1. 错。`RUNNING` 描述整个任务正在执行，不能区分内部问答阶段。\n> 2. 错。前者表示成功提交请求，后者可能因超时返回；还应核查 `done()`。\n> 3. `done()`。STEP 07 可写为 `chat_task is None or chat_task.done()`。\n\n### 5.4 思考题\n\n1. 机器人说完一句话、说“停一下”打断它、调用 `cancel()`，对整个会话分别有什么影响？结合§4.1的状态图，解释为什么不能把“停止请求已发出”直接当成“待机”。\n2. 如果希望界面自动显示“正在聆听”“正在生成”“正在说话”，仅凭本课的 `TaskHandle` 是否足够？还需要接口提供什么信号？请用本课已核实的能力说明理由，不需要编写新接口。\n'))
